<script>
  import { checkForAccessibleName } from '@splendidlabz/utils/dom'
  import { useActions } from '../../../actions/use-actions'
  import { init } from '../../../utils'
  import { comboboxOptions } from './combobox.svelte.js'

  /**
   * @import { Snippet } from 'svelte'
   */

  /**
   * @typedef {object} ComboboxOptionsProps
   * @property {string} id Matches the input's `target`
   * @property {HTMLDivElement | null} [ref]
   * @property {string} [class]
   * @property {boolean} [inline] Render in the flow instead of a popover
   * @property {boolean} [multiple] Let more than one option be selected
   * @property {number} [size] How many options to show before scrolling
   * @property {string} [aria-label]
   * @property {string} [aria-labelledby]
   * @property {{ fn: Function, props?: any }[]} [actions] Actions run on the wrapper
   * @property {Snippet} [status] Renders after the listbox
   * @property {Snippet} [check] Replaces the check a selected option shows
   * @property {Snippet} [children] The options
   */

  /** @type {ComboboxOptionsProps & Record<string, any>} */
  let {
    ref = $bindable(null),
    class: klass = '',
    id,
    inline = false,
    multiple = false,
    size = 8,
    'aria-label': ariaLabel,
    'aria-labelledby': ariaLabelledBy,
    actions = [],
    status,
    check,
    children,
    ...rest
  } = $props()

  init(() => {
    if (!id) throw new Error('ComboboxOptions requires an id')
    checkForAccessibleName({
      name: `ComboboxOptions (id: ${id})`,
      ariaLabel,
      ariaLabelledBy,
    })
  })
</script>

<div
  {...rest}
  bind:this={ref}
  {id}
  class="combobox-options {klass}"
  popover={inline ? null : 'manual'}
  use:comboboxOptions={{ multiple, size }}
  use:useActions={actions}
>
  <ul
    id="{id}-listbox"
    aria-label={ariaLabel}
    aria-labelledby={ariaLabelledBy}
    role="listbox"
    tabindex="-1"
  >
    {@render children?.()}
  </ul>

  {@render status?.()}

  <!-- prepareOptions copies this into every option, since Svelte can't render into slot options -->
  <div class="option-check-source" hidden>
    <span class="option-check" aria-hidden="true">
      {#if check}
        {@render check()}
      {:else}
        <svg fill="none" height="24" viewBox="0 0 24 24" width="24">
          <path
            d="M5 12L10 17L20 7"
            stroke="currentcolor"
            stroke-linecap="round"
            stroke-linejoin="round"
            stroke-width="2"
          />
        </svg>
      {/if}
    </span>
  </div>
</div>
